package com.emos.improvementknowledge.application;
import com.emos.attentionfollowthrough.application.FollowUpAttentionPort;import org.springframework.beans.factory.ObjectProvider;import org.springframework.beans.factory.annotation.Value;import org.springframework.stereotype.Service;import org.springframework.transaction.annotation.Transactional;import org.springframework.boot.autoconfigure.condition.ConditionalOnProperty;import java.time.*;import java.util.*;
@Service @ConditionalOnProperty(name="emos.persistence.enabled",havingValue="true",matchIfMissing=true) public class JiraFollowUpService{private final FollowUpRepository followUps;private final ObjectProvider<JiraIssuePort> jira;private final FollowUpAttentionPort attention;private final Clock clock;private final Set<String> completed;private final Set<String> rationale;
 public JiraFollowUpService(FollowUpRepository f,ObjectProvider<JiraIssuePort> j,FollowUpAttentionPort a,Clock c,@Value("${emos.jira.completed-statuses:Done}") String completed,@Value("${emos.jira.rationale-statuses:Cancelled,Rejected,Won't Do}") String rationale){this.followUps=f;this.jira=j;this.attention=a;this.clock=c;this.completed=values(completed);this.rationale=values(rationale);}
 @Transactional public FollowUpRefreshResult refresh(FollowUpId id){var current=followUps.find(id).orElseThrow();var provider=jira.getIfAvailable();if(provider==null)throw new ImprovementValidationException("Jira integration is disabled");var observed=provider.observe(current.issue());var rationaleRequired=!observed.accessible()||rationale.contains(normalize(observed.status()))||normalize(observed.status()).equals("deleted");var done=observed.accessible()&&completed.contains(normalize(observed.status()))&&!rationaleRequired;var wasClosed=current.state().equals("CLOSED");var state=done?"CLOSED":"OPEN";var updated=new FollowUpRecord(current.id(),current.caseId(),current.issue(),current.reviewDate(),state,observed.status(),observed.observedAt(),observed.accessible(),rationaleRequired);followUps.save(updated);if(done)attention.resolveReviewAttention(current.caseId(),observed.observedAt());else if(wasClosed||!current.reviewDate().isAfter(LocalDate.now(clock)))attention.ensureReviewAttention(current.caseId(),observed.observedAt(),rationaleRequired?"Final rationale required":"Improvement review overdue");return new FollowUpRefreshResult(state,observed.status(),observed.observedAt(),rationaleRequired);}
 private static Set<String> values(String csv){var out=new HashSet<String>();for(var value:csv.split(","))out.add(normalize(value));return out;}private static String normalize(String value){return value==null?"":value.trim().toLowerCase(Locale.ROOT);}}
